import solution
from solution import rescale_counters


class RescaleCountersTests(unittest.TestCase):
    def test_public_api(self):
        public_names = {name for name in vars(solution) if not name.startswith("_")}
        self.assertEqual(public_names, {"rescale_counters"})
        self.assertTrue(callable(rescale_counters))

    def test_normal_scaling_clamping_and_half_up_rounding(self):
        self.assertEqual(
            rescale_counters("0;5;10;-3;+7", 9),
            [0, 5, 9, 0, 6],
        )

    def test_rounding_below_and_at_half(self):
        self.assertEqual(rescale_counters("1;3;4;6", 5), [1, 3, 3, 5])

    def test_malformed_fields_produce_none_and_do_not_affect_peak(self):
        self.assertEqual(
            rescale_counters("10;garbage;20;4.5;1_000;+ 7", 10),
            [5, None, 10, None, None, None],
        )

    def test_empty_text_and_empty_fields_are_preserved(self):
        self.assertEqual(rescale_counters("", 10), [None])
        self.assertEqual(rescale_counters(";;", 10), [None, None, None])
        self.assertEqual(rescale_counters("1;;3;", 6), [2, None, 6, None])

    def test_surrounding_whitespace_and_signs(self):
        self.assertEqual(
            rescale_counters("  +12  ;\t-3\n; 0006 ; +0 ; -0 ", 8),
            [8, 0, 4, 0, 0],
        )

    def test_only_ascii_decimal_digits_are_accepted(self):
        self.assertEqual(
            rescale_counters("１２;١٢;12;²;+٣;-４", 7),
            [None, None, 7, None, None, None],
        )

    def test_no_valid_fields(self):
        self.assertEqual(
            rescale_counters(" ;word;4.0;--; + 1", 99),
            [None, None, None, None, None],
        )

    def test_zero_peak_maps_every_valid_field_to_zero(self):
        self.assertEqual(
            rescale_counters("-999;0;+0;-1;bad", 100),
            [0, 0, 0, 0, None],
        )

    def test_zero_ceiling(self):
        self.assertEqual(
            rescale_counters("1;2;-5;bad", 0),
            [0, 0, 0, None],
        )

    def test_arbitrarily_large_integers_remain_exact(self):
        value = 10 ** 200
        text = f"{value};{2 * value};-{3 * value}"
        self.assertEqual(rescale_counters(text, 3), [2, 3, 0])

    def test_results_are_deterministic_and_newly_allocated(self):
        text = "1;bad;2"
        first = rescale_counters(text, 10)
        second = rescale_counters(text, 10)
        self.assertEqual(first, [5, None, 10])
        self.assertEqual(second, first)
        self.assertIsNot(first, second)
        first[0] = 999
        self.assertEqual(second, [5, None, 10])
        self.assertEqual(rescale_counters(text, 10), [5, None, 10])


